  AgentLoopConfig config,
  ToolExecutor toolExecutor,
  CancelToken? cancelToken,
  AgentEventSink emit,
) {
  final hasSequentialToolCall = toolCalls.any((toolCall) {
    final tool = _findTool(context, toolCall.name);
